91	/// Advisory parallel page-cache prefetch for a whole-checkpoint load;
92	/// the loader never depends on it. Dropping cancels and joins the workers, and
93	/// failures are aggregated into one warning with the first cause retained.
94	pub struct WeightPrefetch {
95	    cancel: Arc<AtomicBool>,
96	    stats: Arc<PrefetchStats>,
97	    unreadable_shards: usize,
98	    spawn_failures: usize,
99	    workers: Vec<std::thread::JoinHandle<()>>,
100	}
101	
102	#[derive(Default)]
103	struct PrefetchStats {
104	    read_errors: AtomicUsize,
105	    first_error: Mutex<Option<String>>,
106	}
107	
108	impl PrefetchStats {
109	    fn record_first_error(&self, message: impl FnOnce() -> String) {
110	        let mut slot = match self.first_error.lock() {
111	            Ok(guard) => guard,
112	            Err(poisoned) => poisoned.into_inner(),
113	        };
114	        if slot.is_none() {
115	            *slot = Some(message());
116	        }
117	    }
118	}
