351	fn tensor_bf16_bytes<'d>(
352	    tensor: &safetensors::tensor::TensorView<'d>,
353	    name: &str,
354	) -> Result<&'d [u8]> {
355	    anyhow::ensure!(
356	        tensor.dtype() == Dtype::BF16,
357	        "Tensor '{name}': expected dtype BF16, got {:?}",
358	        tensor.dtype()
359	    );
360	    let data = tensor.data();
361	    anyhow::ensure!(
362	        data.len().is_multiple_of(std::mem::size_of::<bf16>()),
363	        "Tensor '{name}': {} bytes is not a whole number of bf16 elements",
364	        data.len()
365	    );
366	    Ok(data)
367	}
