396	/// Typed F32 payload with dtype and 1D-shape validation. Aligned payloads
397	/// borrow zero-copy; misaligned ones (legal in safetensors) decode
398	/// little-endian into an owned buffer, since a misaligned f32 view is UB.
399	#[allow(clippy::cast_ptr_alignment)]
400	fn tensor_f32_cow<'d>(
401	    tensor: &safetensors::tensor::TensorView<'d>,
402	    name: &str,
403	) -> Result<Cow<'d, [f32]>> {
404	    anyhow::ensure!(
405	        tensor.dtype() == Dtype::F32,
406	        "Tensor '{name}': expected dtype F32, got {:?}",
407	        tensor.dtype()
408	    );
409	    anyhow::ensure!(
410	        tensor.shape().len() == 1,
411	        "Tensor '{name}': expected 1D shape, got {:?}",
412	        tensor.shape()
413	    );
414	    let data = tensor.data();
415	    anyhow::ensure!(
416	        data.len().is_multiple_of(std::mem::size_of::<f32>()),
417	        "Tensor '{name}': {} bytes is not a whole number of f32 elements",
418	        data.len()
419	    );
420	    if (data.as_ptr() as usize).is_multiple_of(std::mem::align_of::<f32>()) {
421	        // SAFETY: alignment checked; any bit pattern is a valid f32.
422	        Ok(Cow::Borrowed(unsafe {
423	            std::slice::from_raw_parts(
424	                data.as_ptr().cast::<f32>(),
425	                data.len() / std::mem::size_of::<f32>(),
426	            )
427	        }))
428	    } else {
429	        Ok(Cow::Owned(
430	            data.as_chunks::<4>()
431	                .0
432	                .iter()
433	                .map(|&b| f32::from_le_bytes(b))
434	                .collect(),
435	        ))
436	    }
437	}
