456	enum PendingUpload<'d> {
457	    Contiguous { src: &'d [u8], dst_at: u64 },
458	    ColShard { src: &'d [u8], plan: ColShardPlan },
459	    Vector { src: Cow<'d, [bf16]>, dst_at: u64 },
460	}
