462	fn bf16_bytes(src: &[bf16]) -> &[u8] {
463	    // bf16 is a plain two-byte value; a byte view of it is always valid.
464	    unsafe { std::slice::from_raw_parts(src.as_ptr().cast(), std::mem::size_of_val(src)) }
465	}
