467	struct Slot {
468	    data: Option<CudaSlice<bf16>>,
469	    rows: usize,
470	    cols: usize,
471	}
472	
473	struct VecSlot {
474	    data: Option<CudaSlice<bf16>>,
475	    len: usize,
476	}
