478	/// Validating BF16 checkpoint loader backed by pinned staging: every method
479	/// checks dtype and config-derived dimensions at the load boundary; payload
480	/// alignment is not required. Uploads run in [`Self::finish`], after every
481	/// tensor has been validated.
482	pub struct StagedWeightLoader<'a> {
483	    ctx: &'a DeviceContext,
484	    stager: WeightStager,
485	    shards: &'a [SafeTensors<'a>],
486	    weight_map: &'a HashMap<String, usize>,
487	    slots: Vec<Slot>,
488	    vec_slots: Vec<VecSlot>,
489	    pending: Vec<PendingUpload<'a>>,
490	    retained: Vec<Vec<bf16>>,
491	    finished: bool,
492	    failed: bool,
493	    alloc_ms: f64,
494	}
495	
496	impl<'a> StagedWeightLoader<'a> {
497	    pub fn new(
498	        ctx: &'a DeviceContext,
499	        shards: &'a [SafeTensors<'a>],
500	        weight_map: &'a HashMap<String, usize>,
501	    ) -> Result<Self> {
502	        Ok(Self {
503	            ctx,
504	            stager: WeightStager::new(ctx)?,
505	            shards,
506	            weight_map,
507	            slots: Vec::new(),
508	            vec_slots: Vec::new(),
509	            pending: Vec::new(),
510	            retained: Vec::new(),
511	            finished: false,
512	            failed: false,
513	            alloc_ms: 0.0,
514	        })
515	    }
516	
517	    fn ensure_recording(&self) -> Result<()> {
518	        anyhow::ensure!(
519	            !self.finished && !self.failed,
520	            "staged loader already finished"
521	        );
522	        Ok(())
523	    }
524	
525	    fn push_slot(&mut self, data: CudaSlice<bf16>, rows: usize, cols: usize) -> SlotId {
526	        self.slots.push(Slot {
527	            data: Some(data),
528	            rows,
529	            cols,
530	        });
531	        SlotId(self.slots.len() - 1)
532	    }
533	
534	    /// Executes every recorded upload; must run before [`Self::take`].
535	    pub fn finish(&mut self) -> Result<()> {
536	        anyhow::ensure!(
537	            !self.finished && !self.failed,
538	            "staged loader already finished"
539	        );
540	        // Poisoned until every upload lands; a failed finish cannot retry
541	        // vacuously over the drained op list.
542	        self.failed = true;
543	        let uploads = self.pending.len();
544	        let t_upload = std::time::Instant::now();
545	        if let Err(err) = self.execute_uploads() {
546	            // Soundness closes here, not in Drop (skippable via `mem::forget`):
547	            // no submitted copy may outlive this call unresolved.
548	            staging::drain_or_abort(&self.ctx.stream, "staged upload failure");
549	            self.retained.clear();
550	            return Err(err);
551	        }
552	        self.retained.clear();
553	        self.failed = false;
554	        self.finished = true;
555	        info!(
556	            "weight load: {} uploads, alloc_api_wall {:.0}ms, execute_and_drain_wall {:.0}ms",
557	            uploads,
558	            self.alloc_ms,
559	            t_upload.elapsed().as_secs_f64() * 1e3
560	        );
561	        Ok(())
562	    }
563	
564	    fn execute_uploads(&mut self) -> Result<()> {
565	        for op in std::mem::take(&mut self.pending) {
566	            match op {
567	                // SAFETY: the destination is owned by `self.slots` (`take`
568	                // refuses to hand it out before a successful finish) and the
569	                // range was validated by prepare/prepare_cols at record time.
570	                PendingUpload::Contiguous { src, dst_at } => unsafe {
571	                    self.stager.upload_at(src, dst_at)?;
572	                },
573	                PendingUpload::ColShard { src, plan } => unsafe {
574	                    self.stager.upload_cols_at(src, &plan)?;
575	                },
576	                // SAFETY: destination validated at record time; sources
577	                // outlive the drain (borrowed: shards; owned: retained first).
578	                PendingUpload::Vector { src, dst_at } => {
579	                    let bytes = match src {
580	                        Cow::Borrowed(borrowed) => bf16_bytes(borrowed),
581	                        Cow::Owned(owned) => {
582	                            self.retained.push(owned);
583	                            bf16_bytes(self.retained.last().expect("just pushed"))
584	                        }
585	                    };
586	                    unsafe {
587	                        memcpy_htod_async(dst_at, bytes, self.ctx.stream.cu_stream())
588	                            .map_err(|e| anyhow::anyhow!("vector upload failed: {e}"))?;
589	                    }
590	                }
591	            }
592	        }
593	        self.ctx.sync()
594	    }
595	
596	    /// Redeems a recorded matrix after a successful [`Self::finish`].
597	    pub fn take(&mut self, slot: SlotId) -> DeviceMatrix {
598	        assert!(self.finished, "take before successful finish");
599	        let slot = &mut self.slots[slot.0];
600	        DeviceMatrix {
601	            data: slot.data.take().expect("slot already taken"),
602	            rows: slot.rows,
603	            cols: slot.cols,
604	        }
605	    }
