607	    fn tensor_2d(&self, name: &str, rows: usize, cols: usize) -> Result<&'a [u8]> {
608	        let tensor = find_tensor(self.shards, self.weight_map, name)?;
609	        let shape = tensor.shape();
610	        anyhow::ensure!(
611	            shape.len() == 2,
612	            "Tensor '{name}' expected 2D, got shape {shape:?}"
613	        );
614	        anyhow::ensure!(
615	            shape[0] == rows && shape[1] == cols,
616	            "Tensor '{name}' has shape {shape:?}, config expects [{rows}, {cols}]"
617	        );
618	        tensor_bf16_bytes(&tensor, name)
619	    }
620	
621	    fn alloc_timed(&mut self, elems: usize, name: &str) -> Result<CudaSlice<bf16>> {
622	        let t = std::time::Instant::now();
623	        // SAFETY: overwritten by its recorded upload before `take` can
624	        // expose it.
625	        let data = unsafe { self.ctx.stream.alloc::<bf16>(elems) }
626	            .map_err(|e| anyhow::anyhow!("Alloc failed for '{name}': {e}"))?;
627	        self.alloc_ms += t.elapsed().as_secs_f64() * 1e3;
628	        Ok(data)
629	    }
630	
631	    pub fn matrix(&mut self, name: &str, rows: usize, cols: usize) -> Result<SlotId> {
632	        self.ensure_recording()?;
633	        let src = self.tensor_2d(name, rows, cols)?;
634	        let mut data = self.alloc_timed(rows * cols, name)?;
635	        let dst_at = staging::prepare(&self.ctx.stream, src, &mut data, 0)?;
636	        self.pending.push(PendingUpload::Contiguous { src, dst_at });
637	        Ok(self.push_slot(data, rows, cols))
638	    }
639	
640	    /// Row-concatenation of `parts`, each a validated row range of its
641	    /// source tensor; all sources must have exactly `cols` columns.
642	    pub fn fused_rows(&mut self, cols: usize, parts: &[FusedPart]) -> Result<SlotId> {
643	        self.ensure_recording()?;
644	        anyhow::ensure!(!parts.is_empty(), "fused load needs at least one part");
645	        let mut total_rows = 0usize;
646	        let mut srcs = Vec::with_capacity(parts.len());
647	        for part in parts {
648	            let name = part.name;
649	            let full = self.tensor_2d(name, part.src_rows, cols)?;
650	            anyhow::ensure!(
651	                part.row_offset
652	                    .checked_add(part.rows)
653	                    .is_some_and(|end| end <= part.src_rows),
654	                "row range out of bounds for '{name}': row_offset={} rows={} total_rows={}",
655	                part.row_offset,
656	                part.rows,
657	                part.src_rows
658	            );
659	            let elem = std::mem::size_of::<bf16>();
660	            srcs.push(
661	                &full[part.row_offset * cols * elem..(part.row_offset + part.rows) * cols * elem],
662	            );
663	            total_rows += part.rows;
664	        }
665	        let mut data = self.alloc_timed(total_rows * cols, parts[0].name)?;
666	        let mut dst_offset = 0;
667	        for src in srcs {
668	            let dst_at = staging::prepare(&self.ctx.stream, src, &mut data, dst_offset)?;
669	            self.pending.push(PendingUpload::Contiguous { src, dst_at });
670	            dst_offset += src.len() / std::mem::size_of::<bf16>();
671	        }
672	        Ok(self.push_slot(data, total_rows, cols))
673	    }
674	
675	    /// `take` columns starting at `col_offset` of a source tensor validated
676	    /// to exactly `src_rows` x `src_cols` before anything is allocated.
677	    pub fn col_shard(
678	        &mut self,
679	        name: &str,
680	        src_rows: usize,
681	        src_cols: usize,
682	        col_offset: usize,
683	        take: usize,
684	    ) -> Result<SlotId> {
685	        self.ensure_recording()?;
686	        let full = self.tensor_2d(name, src_rows, src_cols)?;
687	        anyhow::ensure!(
688	            col_offset
689	                .checked_add(take)
690	                .is_some_and(|end| end <= src_cols),
691	            "col range out of bounds for '{name}': col_offset={col_offset} take={take} total_cols={src_cols}"
692	        );
693	        let mut data = self.alloc_timed(src_rows * take, name)?;
694	        let plan = staging::prepare_cols(
695	            &self.ctx.stream,
696	            full,
697	            src_cols,
698	            col_offset,
699	            take,
700	            &mut data,
701	        )?;
702	        self.pending
703	            .push(PendingUpload::ColShard { src: full, plan });
704	        Ok(self.push_slot(data, src_rows, take))
705	    }
