707	    /// Small tensors; uploaded as plain pageable copies.
708	    pub fn vector(&mut self, name: &str, len: usize) -> Result<VecSlotId> {
709	        self.ensure_recording()?;
710	        let tensor = find_tensor(self.shards, self.weight_map, name)?;
711	        let shape = tensor.shape();
712	        anyhow::ensure!(
713	            shape.len() == 1 && shape[0] == len,
714	            "Tensor '{name}' has shape {shape:?}, config expects [{len}]"
715	        );
716	        let src = tensor_bf16_cow(&tensor, name)?;
717	        let mut data = self.alloc_timed(len, name)?;
718	        let dst_at = staging::prepare(&self.ctx.stream, bf16_bytes(&src), &mut data, 0)?;
719	        self.pending.push(PendingUpload::Vector { src, dst_at });
720	        self.vec_slots.push(VecSlot {
721	            data: Some(data),
722	            len,
723	        });
724	        Ok(VecSlotId(self.vec_slots.len() - 1))
725	    }
726	
727	    /// Redeems a recorded vector after a successful [`Self::finish`].
728	    pub fn take_vec(&mut self, slot: VecSlotId) -> DeviceVec {
729	        assert!(self.finished, "take before successful finish");
730	        let slot = &mut self.vec_slots[slot.0];
731	        DeviceVec {
732	            data: slot.data.take().expect("slot already taken"),
733	            len: slot.len,
734	        }
735	    }
736	}
