788	pub fn load_tensor_2d_row_shard(
789	    ctx: &DeviceContext,
790	    shards: &[SafeTensors],
791	    weight_map: &HashMap<String, usize>,
792	    name: &str,
793	    row_offset: usize,
794	    rows: usize,
795	) -> Result<DeviceMatrix> {
796	    let tensor = find_tensor(shards, weight_map, name)?;
797	    let (total_rows, cols) = tensor_2d_dims(&tensor, name)?;
798	    check_row_range(name, row_offset, rows, total_rows)?;
799	    let elems = tensor_bf16_cow(&tensor, name)?;
800	    let start = row_offset * cols;
801	    let end = (row_offset + rows) * cols;
802	    DeviceMatrix::from_host(ctx, &elems[start..end], rows, cols)
803	}
804	
805	fn gather_cols(
806	    elems: &[bf16],
807	    rows: usize,
808	    total_cols: usize,
809	    col_offset: usize,
810	    take: usize,
811	) -> Vec<bf16> {
812	    let mut host = vec![bf16::ZERO; rows * take];
813	    for row in 0..rows {
814	        let src = row * total_cols + col_offset;
815	        let dst = row * take;
816	        host[dst..dst + take].copy_from_slice(&elems[src..src + take]);
817	    }
818	    host
819	}
