821	pub fn load_tensor_2d_col_shard(
822	    ctx: &DeviceContext,
823	    shards: &[SafeTensors],
824	    weight_map: &HashMap<String, usize>,
825	    name: &str,
826	    col_offset: usize,
827	    cols: usize,
828	) -> Result<DeviceMatrix> {
829	    let tensor = find_tensor(shards, weight_map, name)?;
830	    let (rows, total_cols) = tensor_2d_dims(&tensor, name)?;
831	    if col_offset + cols > total_cols {
832	        return Err(anyhow::anyhow!(
833	            "2D col shard out of bounds for '{}': col_offset={} cols={} total_cols={}",
834	            name,
835	            col_offset,
836	            cols,
837	            total_cols
