845	/// Load a 2D tensor assembled from multiple row ranges of one source tensor,
846	/// stitched in `ranges` order: each entry is (row_offset, rows).
847	pub fn load_tensor_2d_row_stitch(
848	    ctx: &DeviceContext,
849	    shards: &[SafeTensors],
850	    weight_map: &HashMap<String, usize>,
851	    name: &str,
852	    ranges: &[(usize, usize)],
853	) -> Result<DeviceMatrix> {
854	    let tensor = find_tensor(shards, weight_map, name)?;
855	    let (total_rows, cols) = tensor_2d_dims(&tensor, name)?;
856	    let mut total = 0usize;
857	    for &(row_offset, rows) in ranges {
858	        check_row_range(name, row_offset, rows, total_rows)?;
859	        total += rows;
860	    }
861	    let elems = tensor_bf16_cow(&tensor, name)?;
862	    let mut host = Vec::with_capacity(total * cols);
863	    for &(row_offset, rows) in ranges {
864	        let start = row_offset * cols;
865	        host.extend_from_slice(&elems[start..start + rows * cols]);
866	    }
867	    DeviceMatrix::from_host(ctx, &host, total, cols)
868	}
