870	/// Load a 1D BF16 tensor assembled from multiple element ranges of one source
871	/// tensor, stitched in `ranges` order: each entry is (offset, len).
872	pub fn load_tensor_1d_stitch(
873	    ctx: &DeviceContext,
874	    shards: &[SafeTensors],
875	    weight_map: &HashMap<String, usize>,
876	    name: &str,
877	    ranges: &[(usize, usize)],
878	) -> Result<DeviceVec> {
879	    let tensor = find_tensor(shards, weight_map, name)?;
880	    let elems = tensor_bf16_cow(&tensor, name)?;
881	    let mut total = 0usize;
882	    for &(offset, len) in ranges {
883	        if offset + len > elems.len() {
884	            return Err(anyhow::anyhow!(
885	                "1D stitch out of bounds for '{}': offset={} len={} total_len={}",
886	                name,
887	                offset,
888	                len,
889	                elems.len()
890	            ));
891	        }
892	        total += len;
893	    }
894	    let mut host = Vec::with_capacity(total);
895	    for &(offset, len) in ranges {
896	        host.extend_from_slice(&elems[offset..offset + len]);
897	    }
898	    DeviceVec::from_host(ctx, &host)
899	}
