943	/// Load a 1D I64 tensor into a host `Vec<i64>`.
944	///
945	/// For small integer lookup tables that live on the host (e.g. EAGLE-3's `d2t`
946	/// draft→target vocab offset map), not weights destined for a GEMM.
947	pub fn load_tensor_i64_host(
948	    shards: &[SafeTensors],
949	    weight_map: &HashMap<String, usize>,
950	    name: &str,
951	) -> Result<Vec<i64>> {
952	    let tensor = find_tensor(shards, weight_map, name)?;
953	
954	    if tensor.dtype() != Dtype::I64 {
955	        return Err(anyhow::anyhow!(
956	            "I64 tensor '{}': expected dtype I64, got {:?}",
957	            name,
958	            tensor.dtype()
959	        ));
960	    }
961	    if tensor.shape().len() != 1 {
962	        return Err(anyhow::anyhow!(
963	            "I64 tensor '{}': expected 1D, got shape {:?}",
964	            name,
965	            tensor.shape()
966	        ));
967	    }
968	    let data = tensor.data();
969	    if data.len() % 8 != 0 {
970	        return Err(anyhow::anyhow!(
971	            "I64 tensor '{}': data length {} not multiple of 8",
972	            name,
973	            data.len()
974	        ));
975	    }
976	    Ok(data
977	        .as_chunks::<8>()
978	        .0
979	        .iter()
980	        .map(|&b| i64::from_le_bytes(b))
981	        .collect())
982	}
