1009	/// Load shard info with fixup for mismatched shard filenames in index.json.
1010	///
1011	/// Some models (e.g., Qwen3.5) have index.json with shard filenames like
1012	/// `model.safetensors-00001-of-00002.safetensors` while actual files are
1013	/// `model-00001-of-00002.safetensors`. This function detects and fixes that.
1014	pub fn load_shard_info_fixed(model_path: &str) -> Result<(Vec<String>, HashMap<String, usize>)> {
1015	    let (mut shard_files, weight_map) = load_shard_info(model_path)?;
1016	
1017	    for path in &mut shard_files {
1018	        if !std::path::Path::new(path).exists() {
1019	            // Try replacing "model.safetensors-" with "model-" in filename
1020	            let filename = std::path::Path::new(path)
1021	                .file_name()
1022	                .unwrap()
1023	                .to_str()
1024	                .unwrap();
1025	            if let Some(rest) = filename.strip_prefix("model.safetensors-") {
1026	                let fixed = format!("{}/model-{}", model_path, rest);
1027	                if std::path::Path::new(&fixed).exists() {
1028	                    log::info!(
1029	                        "Fixed shard path: {} -> {}",
1030	                        filename,
1031	                        std::path::Path::new(&fixed)
1032	                            .file_name()
1033	                            .unwrap()
1034	                            .to_str()
1035	                            .unwrap()
1036	                    );
1037	                    *path = fixed;
1038	                    continue;
1039	                }
1040	            }
1041	            return Err(anyhow::anyhow!("Shard file not found: {}", path));
1042	        }
1043	    }
1044	
1045	    Ok((shard_files, weight_map))
1046	}
