1058	    #[test]
1059	    fn tensor_f32_cow_borrows_aligned_and_decodes_unaligned() {
1060	        let vals: [u32; 4] = [0x3f80_0000, 0x0000_0001, 0xbf12_3456, 0x7f80_0001];
1061	        let mut bytes = vec![0u8; vals.len() * 4 + 3];
1062	        // A Vec<u8> base has no alignment guarantee; derive both offsets from
1063	        // the actual address so each branch is forced deterministically.
1064	        let base = bytes.as_ptr() as usize;
1065	        let aligned_off = base.next_multiple_of(4) - base;
1066	        for (off, expect_borrowed) in [(aligned_off, true), (aligned_off + 1, false)] {
1067	            for (i, v) in vals.iter().enumerate() {
1068	                bytes[off + i * 4..off + i * 4 + 4].copy_from_slice(&v.to_le_bytes());
1069	            }
1070	            let view = TensorView::new(
1071	                Dtype::F32,
1072	                vec![vals.len()],
1073	                &bytes[off..off + vals.len() * 4],
1074	            )
1075	            .unwrap();
1076	            let cow = tensor_f32_cow(&view, "w").unwrap();
1077	            assert_eq!(
1078	                matches!(cow, Cow::Borrowed(_)),
1079	                expect_borrowed,
1080	                "off={off}"
1081	            );
1082	            let got: Vec<u32> = cow.iter().map(|f| f.to_bits()).collect();
1083	            assert_eq!(got, vals, "off={off}");
1084	        }
1085	    }
