1098	        let vals: [u16; 4] = [0x3f80, 0x0001, 0xbf12, 0x7fff];
1099	        let mut bytes = vec![0u8; vals.len() * 2 + 3];
1100	        // A Vec<u8> base has no alignment guarantee; derive both offsets from
