//! Safetensors weight loading.

use std::borrow::Cow;
use std::collections::HashMap;
use std::fs;
use std::os::unix::fs::FileExt;
use std::os::unix::io::AsRawFd;
use std::sync::Arc;
use std::sync::Mutex;
