#[test]
fn tp2_row_and_col_shards_stitch_back() {
    let rows = 8usize;   // out 维
    let cols = 6usize;   // in 维
    let values: Vec<bf16> = (0..(rows * cols))
        .map(|i| bf16::from_f32(i as f32))
        .collect();
    let payload: Vec<u8> = values
        .iter()
        .flat_map(|v| v.to_bits().to_le_bytes())
        .collect();
    let view = TensorView::new(Dtype::BF16, vec![rows, cols], &payload).unwrap();
    let bytes = safetensors::serialize([("w".to_string(), view)], None).unwrap();
    let shards = vec![SafeTensors::deserialize(&bytes).unwrap()];
    let weight_map = HashMap::new();

    let ctx = DeviceContext::new().unwrap();

    // ---- row shard: rank r 取第 r 段输出行，纵向拼接应还原原矩阵 ----
    let mut row_ranks = Vec::new();
    for r in 0..2 {
        let m = load_tensor_2d_row_shard(&ctx, &shards, &weight_map, "w", r * (rows / 2), rows / 2).unwrap();
        assert_eq!((m.rows, m.cols), (rows / 2, cols));
        row_ranks.push(ctx.stream.clone_dtoh(&m.data).unwrap());
    }
    let stitched_rows: Vec<bf16> = row_ranks.into_iter().flatten().collect();
    assert_eq!(stitched_rows, values, "TP2 row shard 纵向拼回应等于原矩阵");

    // ---- col shard: rank r 取第 r 段输入列，横向拼接应还原原矩阵 ----
    let mut col_parts = Vec::new();
    for r in 0..2 {
        let m = load_tensor_2d_col_shard(&ctx, &shards, &weight_map, "w", r * (cols / 2), cols / 2).unwrap();
        assert_eq!((m.rows, m.cols), (rows, cols / 2));
        col_parts.push(ctx.stream.clone_dtoh(&m.data).unwrap());
    }
    let mut stitched_cols = Vec::with_capacity(rows * cols);
    for row in 0..rows {
        for part in &col_parts {
            stitched_cols.extend_from_slice(&part[row * (cols / 2)..(row + 1) * (cols / 2)]);
        }
    }
    assert_eq!(stitched_cols, values, "TP2 col shard 横向逐行拼回应等于原矩阵");
}
